function dateValue(s) {
  return new Date(s + "T00:00:00");
}
function detailRows(kind, map) {
  const rows = [["维度", "名称", "日期", "订单数量", "销售数量", "发货金额"]];
  for (const [name, values] of Object.entries(map)) {
    for (const [date, orders, sales, amount] of values) {
      rows.push([kind, name, dateValue(date), orders, sales, amount]);
    }
  }
  return rows;
}
function styleHeader(range, fill) {
  range.format = {
    fill: fill || "#0F766E",
    font: { bold: true, color: "#FFFFFF" },
    wrapText: true,
    horizontalAlignment: "center",
    verticalAlignment: "center",
  };
  range.format.borders = { preset: "outside", style: "thin", color: fill || "#0F766E" };
}
function styleTotals(range) {
  range.format = { fill: "#E2E8F0", font: { bold: true, color: "#0F172A" } };
  range.format.borders = { top: { style: "thin", color: "#64748B" } };
}
function styleDetail(sheet, lastRow, tableName) {
  sheet.showGridLines = false;
  styleHeader(sheet.getRange("A1:F1"));
  sheet.getRange("A1:F1").format.rowHeight = 28;
  sheet.getRange("C2:C" + lastRow).setNumberFormat("yyyy-mm-dd");
  sheet.getRange("D2:E" + lastRow).setNumberFormat("#,##0");
  sheet.getRange("F2:F" + lastRow).setNumberFormat("#,##0.00");
  sheet.getRange("A1:F" + lastRow).format.borders = {
    insideHorizontal: { style: "thin", color: "#E2E8F0" },
    bottom: { style: "thin", color: "#CBD5E1" },
  };
  sheet.getRange("A1:A" + lastRow).format.columnWidth = 10;
  sheet.getRange("B1:B" + lastRow).format.columnWidth = 16;
  sheet.getRange("C1:C" + lastRow).format.columnWidth = 13;
  sheet.getRange("D1:E" + lastRow).format.columnWidth = 12;
  sheet.getRange("F1:F" + lastRow).format.columnWidth = 14;
  sheet.freezePanes.freezeRows(1);
  sheet.freezePanes.freezeColumns(2);
  const table = sheet.tables.add("A1:F" + lastRow, true, tableName);
  try { table.style = "TableStyleMedium2"; } catch {}
  table.showFilterButton = true;
}
function sumifsFormula(sheetName, metricCol, lastRow, row, withDate) {
  let f = "=SUMIFS('" + sheetName + "'!$" + metricCol + "$2:$" + metricCol + "$" + lastRow +
    ",'" + sheetName + "'!$B$2:$B$" + lastRow + ",$A" + row;
  if (withDate) f += ",'" + sheetName + "'!$C$2:$C$" + lastRow + ",$D$5";
  return f + ")";
}

